"""Append RLS policies/grants for the tables an autogenerated revision creates.

Usage: uv run python scripts/finalize_migration.py migrations/versions/<rev>.py
The table->scope mapping is embedded as a literal so the revision stays reproducible.
"""

from __future__ import annotations

import re
import sys

from rp_api.db import models  # noqa: F401
from rp_api.db.base import Base

MARK = "    # ### end Alembic commands ###"


def main(path: str) -> None:
    src = open(path).read()
    if "TABLE_SCOPES" in src:
        print("already finalized")
        return
    up, _, down = src.partition("def downgrade")
    created = re.findall(r"op\.create_table\(\s*'([a-z_0-9]+)'", up)
    scopes = {t: Base.metadata.tables[t].info.get("scope", "tenant") for t in created}
    literal = "TABLE_SCOPES = {\n" + "".join(f"    {t!r}: {s!r},\n" for t, s in scopes.items()) + "}\n"
    block = (
        "    # ### RLS, grants and integrity triggers (scripts/finalize_migration.py) ###\n"
        "    from rp_api.db.rls import policy_sql\n\n"
        "    for table, scope in TABLE_SCOPES.items():\n"
        "        for stmt in policy_sql(table, scope):\n"
        "            op.execute(stmt)\n"
    )
    up = up.replace(MARK, MARK + "\n" + block, 1)
    up = up.replace("\n\ndef upgrade", "\n\n" + literal + "\n\ndef upgrade", 1)
    open(path, "w").write(up + "def downgrade" + down)
    print(f"finalized {len(scopes)} tables")


if __name__ == "__main__":
    main(sys.argv[1])
